from concurrent.futures import ThreadPoolExecutor
from PIL import Image,ImageOps
import hashlib,json
from produce import EP,request,save
OUT=EP/'image/character-options/v1';OUT.mkdir(parents=True,exist_ok=True)
OPTIONS=[('A','干练偏瘦','Chinese man around 39, lean wiry practical build, long slightly angular face with defined cheekbones, short slightly untidy black hair, clean shaven, alert observant dark eyes, restrained focused expression, small signs of fatigue. A capable experienced tradesman, ordinary appearance, not handsome model.'),('B','结实稳重','Chinese man around 43, solid broad-shouldered average-height build, sturdy forearms, broad square face and short cropped black hair, clean shaven, calm watchful dark eyes, faint forehead lines, composed slightly tired expression, natural working-class appearance. Not a bodybuilder, not a model.'),('C','年长老练','Chinese man around 51, medium lean build with slightly stooped relaxed shoulders, narrow weathered face, short salt-and-pepper hair, very light stubble, crow feet and mild under-eye fatigue, steady kind but unsmiling observant expression, experienced practical ordinary worker, not a caricature.')]
BASE='''Use case: illustration-story. Asset: protagonist appearance candidate for an adult hand-painted cleaning-work story. This episode explicitly replaces former stick figures with human characters. Create ONE full-body adult human man only, in a natural relaxed three-quarter standing pose, entire head, hands and work shoes visible, centered a little left, body fills about 85 percent of image height. Normal realistic adult anatomy about 7 heads tall. Believable facial features, nose, ears, natural skin tones, hair, anatomically readable hands inside gloves. Traditional 2D hand-painted narrative illustration: softly broken ink/pencil contours, opaque gouache-like brush texture, restrained 2-3 broad tonal planes on clothes and skin, subtle reflected room light and grounded foot shadow. Match the attached room's hand-painted rendering, NOT photorealism, NOT 3D, NOT anime, NOT cute cartoon, NOT blank white circular head, NOT stick limbs. Wear faded slate teal-blue utility work jacket with a few practical pockets, sleeves down, dark charcoal work trousers, worn dark rubber work shoes, yellow rubber cleaning gloves worn on both hands. Modest realistic cloth folds, creases, scuffed knees and small localized dirty smudges, clothes not torn. No mask covering face; no hat; no badges, text, logos, symbols, graphic labels, panels, turnaround duplicate figures, weapons or extra props. Expression grounded and reserved, no hero pose. Both arms relaxed with hands separately visible. Attached image is ENVIRONMENT MATERIAL AND LIGHT REFERENCE ONLY: use the same muted sea-green tiles, old grey cabinet surfaces and soft window daylight as a low-detail quiet background, softened edges so facial design and silhouette read clearly. Leave some quiet space around man, no garbage in front obscuring his body. Background and person must share exactly the same painted texture and natural light. Human skin and garment colors integrate with the room, no white studio cutout edge. Full-frame horizontal 16:9. Character identity: '''
def generate(pair):
 index,(key,name,desc)=pair;prompt=BASE+desc
 ref=EP/'image/backgrounds/kitchen-full.png';tag='worker-human-option-'+key.lower()
 src=request(tag,prompt,index,ref,dict(stage='episode-character-candidate',character_id='worker',option=key,name=name,episode_override='用户要求本期弃用简笔小人，改为写实比例二维手绘人物；三款候选未选定',reference_roles={str(ref):'hand-painted material and lighting only; no former character reference'},fact=desc,cast='worker',shot_type='character-fullbody'))
 out=OUT/f'清理垃圾屋_主角{key}_{name}.png'
 with Image.open(src) as im:ImageOps.fit(im.convert('RGB'),(1920,1080),method=Image.Resampling.LANCZOS).save(out)
 return dict(option=key,name=name,file=str(out.relative_to(EP)),sha256=hashlib.sha256(out.read_bytes()).hexdigest(),request=f'logs/requests/{tag}.json')
if __name__=='__main__':
 def worker(seq):return [generate(pair) for pair in seq]
 with ThreadPoolExecutor(max_workers=2) as pool:groups=list(pool.map(worker,[list(enumerate(OPTIONS))[::2],list(enumerate(OPTIONS))[1::2]]))
 rows=sorted([r for group in groups for r in group],key=lambda r:r['option']);save(EP/'qa/character-options.json',dict(status='待目检',options=rows))
 print('CHARACTER_OPTIONS_READY',flush=True)
